# area: context_managers
# hypothesis: An __exit__ annotated to return bool that returns True swallows the exception so execution continues after the with block, while an __exit__ annotated None lets the same exception escape, matching suppress(ValueError).
from contextlib import suppress
from typing import reveal_type


class Swallow:
    def __enter__(self) -> str:
        return 'ok'

    def __exit__(self, exc_type: object, exc: object, tb: object) -> bool:
        return True


class Escape:
    def __enter__(self) -> int:
        return 1

    def __exit__(self, exc_type: object, exc: object, tb: object) -> None:
        return None


def swallowed() -> str:
    with Swallow() as tag:
        reveal_type(tag)
        raise ValueError('gone')
    return 'after-block'


def escapes() -> int:
    with Escape() as n:
        reveal_type(n)
        raise KeyError('escapes')
    return 0


def suppressed() -> str:
    with suppress(ValueError):
        int('x')
        return 'not reached'
    return 'suppressed'


print(swallowed())
print(suppressed())
try:
    print(escapes())
except KeyError as exc:
    print('escaped:', exc)
